using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using SchoolERP.Api.Security;using SchoolERP.Application.Common.Pagination;using SchoolERP.Application.Features.Departments;using SchoolERP.Domain.Enums;using SchoolERP.Domain.Security;using SchoolERP.Shared.Models;
namespace SchoolERP.Api.Controllers.v1;
/// <summary>Manages school-wide and campus-specific departments. Codes are unique per school and lifecycle operations require separate permissions.</summary>
[ApiController,Authorize,Route("api/v1/departments")]public sealed class DepartmentsController(IDepartmentService service):ControllerBase{
 [HttpGet,RequirePermission(PermissionCatalog.Department.View)]public async Task<ActionResult<ApiResponse<PagedResult<DepartmentListItemDto>>>>List([FromQuery]int pageNumber=1,[FromQuery]int pageSize=20,[FromQuery]Guid? campusId=null,[FromQuery]bool schoolWideOnly=false,[FromQuery]DepartmentType? type=null,[FromQuery]DepartmentStatus? status=null,[FromQuery]string? search=null,[FromQuery]string? sortBy=null,[FromQuery]string? sortDirection=null,CancellationToken ct=default)=>Ok(ApiResponse<PagedResult<DepartmentListItemDto>>.Ok(await service.ListAsync(new(pageNumber,pageSize,campusId,schoolWideOnly,type,status,search,sortBy,sortDirection),ct)));
 [HttpGet("{id:guid}"),RequirePermission(PermissionCatalog.Department.View)]public async Task<ActionResult<ApiResponse<DepartmentDetailsDto>>>Get(Guid id,CancellationToken ct)=>Result(await service.GetAsync(id,ct));
 [HttpPost,RequirePermission(PermissionCatalog.Department.Create)]public async Task<ActionResult<ApiResponse<DepartmentDetailsDto>>>Create(CreateDepartmentRequest request,CancellationToken ct){var x=await service.CreateAsync(request,ct);return CreatedAtAction(nameof(Get),new{id=x.Id},ApiResponse<DepartmentDetailsDto>.Ok(x));}
 [HttpPut("{id:guid}"),RequirePermission(PermissionCatalog.Department.Edit)]public async Task<ActionResult<ApiResponse<DepartmentDetailsDto>>>Update(Guid id,UpdateDepartmentRequest request,CancellationToken ct)=>Result(await service.UpdateAsync(id,request,ct));
 [HttpPost("{id:guid}/change-code"),RequirePermission(PermissionCatalog.Department.Edit)]public async Task<ActionResult<ApiResponse<DepartmentDetailsDto>>>ChangeCode(Guid id,ChangeDepartmentCodeRequest request,CancellationToken ct)=>Result(await service.ChangeCodeAsync(id,request,ct));
 [HttpPost("{id:guid}/activate"),RequirePermission(PermissionCatalog.Department.Activate)]public async Task<ActionResult<ApiResponse<DepartmentDetailsDto>>>Activate(Guid id,CancellationToken ct)=>Result(await service.ActivateAsync(id,ct));
 [HttpPost("{id:guid}/deactivate"),RequirePermission(PermissionCatalog.Department.Deactivate)]public async Task<ActionResult<ApiResponse<DepartmentDetailsDto>>>Deactivate(Guid id,CancellationToken ct)=>Result(await service.DeactivateAsync(id,ct));
 [HttpPost("{id:guid}/archive"),RequirePermission(PermissionCatalog.Department.Archive)]public async Task<ActionResult<ApiResponse<DepartmentDetailsDto>>>Archive(Guid id,CancellationToken ct)=>Result(await service.ArchiveAsync(id,ct));
 private ActionResult<ApiResponse<DepartmentDetailsDto>> Result(DepartmentDetailsDto? x)=>x is null?NotFound():Ok(ApiResponse<DepartmentDetailsDto>.Ok(x));}
